const rawText = $input.first().json.content.parts[0].text;
const cleanData = JSON.parse(rawText);

const originalTitle =  $('RSS Feed Trigger').first().json.title;
const originalLink = $('RSS Feed Trigger').first().json.link;

return {
  title: originalTitle,
  link: originalLink,
  summary: cleanData.summary[0],
  category: cleanData.category,
  importance: cleanData.importance
};

const blocks = [
  {
    type: "header",
    text: { type: "plain_text", text: "🚀 Daily Competitor & Market Report" }
  },
  { type: "divider" },
];

for (const item of $json.data) {
  blocks.push(
    {
      type: "section",
      text: { type: "mrkdwn", text: `*${item.title}*\n${item.summary}` },
      accessory: {
        type: "button",
        text: { type: "plain_text", text: "View Article" },
        url: item.link,
      },
    },
    {
      type: "context",
      elements: [
        { type: "mrkdwn", text: `Category: ${item.category} | Importance: ${item.importance}/5` }
      ],
    },
    { type: "divider" }
  );
}

return [{ json: { blocks } }];
